  "id": "autocomplete",
  "name": "Autocomplete",
  "tier": "molecule",
  "description": "Type-ahead input following the HTML autocomplete model: any value is allowed while matching suggestions appear in a keyboard-navigable listbox.",
  "designIntent": "Form fields often need both freedom and guidance — usernames, tags, city names. Autocomplete extends the native autocomplete spec: the input stays a normal controlled input (native autoComplete hints keep working), and an ARIA combobox listbox overlays suggestions. Unlike Search, no option constrains the result.",
  "props": [
    {
      "name": "suggestions",
      "type": "string[]",
      "required": true,
      "description": "Suggestion labels offered while typing; any value may still be entered free-form.",
      "examples": [
        "['react', 'remix', 'astro']"
      ]
    },
    {
      "name": "value",
      "type": "string",
      "required": false,
      "description": "Current text — standard controlled-input contract (wire onValueChange to update it).",
      "examples": [
        "'re'"
      ]
    },
    {
      "name": "defaultValue",
      "type": "string",
      "required": false,
      "description": "Initial text when uncontrolled.",
      "defaultValue": "''",
      "examples": [
        "'react'"
      ]
    },
    {
      "name": "onValueChange",
      "type": "(value: string) => void",
      "required": false,
      "description": "Fires on every keystroke AND on suggestion selection (like a native input's onChange)."
    },
    {
      "name": "emptyText",
      "type": "string",
      "required": false,
      "description": "Shown when no suggestion matches (optional; defaults to 'No suggestions').",
      "examples": [
        "'No matches — press Enter to use your text'"
      ]
    }
  ],
  "examples": [
    {
      "title": "Controlled form field",
      "code": "const [framework, setFramework] = useState('');\n\n<FormField id=\"framework\" label=\"Primary framework\" hint=\"Type or pick a suggestion\">\n  <Autocomplete\n    suggestions={['react', 'remix', 'next', 'vite']}\n    value={framework}\n    onValueChange={setFramework}\n    name=\"framework\"\n    autoComplete=\"off\"\n  />\n</FormField>",
      "description": "onValueChange mirrors native onChange; FormField wires the label and hint."
    },
    {
      "title": "Native autofill hints alongside the custom list",
      "code": "<Autocomplete\n  name=\"country\"\n  autoComplete=\"country-name\"\n  suggestions={countryNames}\n  onValueChange={setCountry}\n/>",
      "description": "The native autoComplete attribute passes through — browser autofill and the suggestion list coexist."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't use Autocomplete for constrained choice",
      "explanation": "Free text is the point of Autocomplete. When only known values are valid (plan tier, enum), use Select or Search so invalid states cannot be typed.",
      "example": "// Avoid: free text for a closed set\n<Autocomplete suggestions={['free','pro']} onValueChange={setPlan} />\n\n// Prefer\n<Select options={plans} value={plan} onChange={setPlan} />"
    },
    {
      "title": "Don't forget to keep state in sync when controlled",
      "explanation": "With value set, React makes the input fully controlled — if onValueChange does not update the parent state, typing appears frozen.",
      "example": "<Autocomplete value={v} onValueChange={setV} suggestions={…} /> // wired\n<Autocomplete value={v} suggestions={…} /> // frozen — bug"
    },
    {
      "title": "Don't block Enter for form submission",
      "explanation": "Enter only consumes the event when a suggestion is actively highlighted — otherwise it should submit the surrounding form. Avoid adding a global keydown handler that always prevents Enter.",
      "example": "// The component already handles this; no extra wiring needed."
    }
  ],
  "accessibility": [
    {
      "feature": "Combobox pattern",
      "implementation": "role=combobox with aria-expanded, aria-controls, aria-autocomplete=list, and aria-activedescendant on the input; suggestions render as role=option with aria-selected",
      "userRequirements": "Provide a name via FormField label or aria-label"
    },
    {
      "feature": "Keyboard operation",
      "implementation": "ArrowDown/ArrowUp highlight suggestions (wrapping), Home/End jump, Enter accepts the highlighted suggestion, Escape closes the list; unhighlighted Enter submits the form natively",
      "userRequirements": "None"
    },
    {
      "feature": "Native autocomplete passthrough",
      "implementation": "The autoComplete attribute is forwarded to the input so browser autofill hints keep working",
      "userRequirements": "Set autoComplete='off' only when suggestions must not clash with browser autofill"
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "Suggestions",
      "guidelines": [
        "Prefer exact known values (tags, usernames)",
        "Dedupe against the current value",
        "Cap lists at ~20 for scannability"
      ],
      "goodExamples": [
        "react",
        "remix"
      ],
      "badExamples": [
        "React!!",
        "react (deprecated?)"
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "FormField",
      "relationship": "Standard form placement — label, hint, and error wiring come free",
      "example": "<FormField id=\"tag\" label=\"Tag\" hint=\"Type to see existing tags\"><Autocomplete suggestions={tags} value={tag} onValueChange={setTag} /></FormField>"
    },
    {
      "component": "Search",
